class FakeMemory:
    """64 KiB of zeroed memory with helpers to poke values."""

    def __init__(self) -> None:
        self.mem = bytearray(0x10000)

    def read(self, address: int, length: int) -> list[int]:
        return list(self.mem[address : address + length])

    def poke(self, address: int, values: list[int] | bytes) -> None:
        self.mem[address : address + len(values)] = bytes(values)


