def pytest_collection_modifyitems(config, items):
    """Skip @pytest.mark.rom tests unless YELLOW_ROM points at a real file."""
    rom = os.environ.get("YELLOW_ROM")
    if rom and Path(rom).is_file():
        return
    skip = pytest.mark.skip(reason="set YELLOW_ROM to your own Pokémon Yellow dump")
    for item in items:
        if "rom" in item.keywords:
            item.add_marker(skip)
